def flatten(nested_list):
    for item in nested_list:
        if isinstance(item, list):
            yield from flatten(item)
        else:
            yield item

# 演示
nested = [[1,2,[3]],4,[5,[6]]]
gen = flatten(nested)
print('第一次遍历:')
for num in gen:
    print(num)
print('遍历完后再次遍历:')
for num in gen:
    print(num)  # 无输出
